# Interface Module - Reda Mahmoud Ali (202507258)\n# This file has functions for searching, sorting, and displaying menus\n# We learned these in Lecture 07 (Algorithms) and Lecture 06 (Output)\n\nimport calculations\n\n# Function to search for a student by ID\ndef search_student_by_id(students, search_id):\n    # Go through each student in the list\n    for student in students:\n        # Check if the ID matches\n        if student['id'] == search_id:\n            # Found the student, return it\n            return student\n    # If we reach here, student not found\n    return None\n\n# Function to search for a student by name\ndef search_student_by_name(students, search_name):\n    results = []\n    search_name = search_name.lower()\n    # Look at each student\n    for student in students:\n        student_name = student['name'].lower()\n        # Check if the search term is in the name\n        if search_name in student_name:\n            results.append(student)\n    return results\n\n# Function to search for a course by code\ndef search_course_by_code(courses, search_code):\n    # Go through all courses\n    for course in courses:\n        # Check if code matches\n        if course['code'] == search_code:\n            return course\n    return None\n\n# Function to sort students by their credits (using Bubble Sort)\n# This is the algorithm we learned in class\ndef sort_students_by_credits(students, registrations, courses):\n    # First, calculate credits for each student\n    student_credits = []\n    for student in students:\n        student_id = student['id']\n        credits = calculations.calculate_total_credits(student_id, registrations, courses)\n        student_credits.append({'student': student, 'credits': credits})\n    \n    # Now sort using Bubble Sort (from Lecture 07)\n    n = len(student_credits)\n    for i in range(n):\n        for j in range(n - 1):\n            # Compare adjacent elements\n            if student_credits[j]['credits'] < student_credits[j + 1]['credits']:\n                # Swap if in wrong order\n                temp = student_credits[j]\n                student_credits[j] = student_credits[j + 1]\n                student_credits[j + 1] = temp\n    \n    return student_credits\n\n# Function to display the main menu\ndef display_main_menu():\n    print("\\n" + "="*50)\n    print("  UNIVERSITY COURSE REGISTRATION SYSTEM")\n    print("="*50)\n    print("1. Login as Admin")\n    print("2. Login as Student")\n    print("0. Exit")\n    print("="*50)\n\n# Function to display admin menu\ndef display_admin_menu():\n    print("\\n" + "="*50)\n    print("       ADMIN MENU")\n    print("="*50)\n    print("1. View All Students")\n    print("2. View All Courses")\n    print("3. Search Student")\n    print("4. Search Course")\n    print("5. View Statistics")\n    print("0. Logout")\n    print("="*50)\n\n# Function to display student menu\ndef display_student_menu(student_name):\n    print("\\n" + "="*50)\n    print("  STUDENT MENU - Welcome " + student_name + "!")\n    print("="*50)\n    print("1. View My Courses")\n    print("2. Register New Course")\n    print("3. Drop Course")\n    print("0. Logout")\n    print("="*50)\n\n# Function to check login\ndef check_login(username, password, students):\n    # Check if admin\n    if username == "admin" and password == "admin123":\n        return "admin"\n    \n    # Check if student\n    for student in students:\n        if student['id'] == username and student['password'] == password:\n            return student\n    \n    # Login failed\n    return None\n\n# Function to display all students in a nice format\ndef display_students(students):\n    print("\\n" + "-"*70)\n    print("ID           Name                     Program    Year")\n    print("-"*70)\n    for student in students:\n        print(student['id'] + "    " + student['name'] + "    " + student['program'] + "         " + student['year'])\n    print("-"*70)\n\n# Function to display all courses\ndef display_courses(courses):\n    print("\\n" + "-"*80)\n    print("Code      Name                              Credits  Days       Time")\n    print("-"*80)\n    for course in courses:\n        print(course['code'] + "    " + course['name'] + "    " + str(course['credits']) + "        " + course['days'] + "  " + course['time'])\n    print("-"*80)
